    Movie(id = 1100042, title = "Maserati: The Brothers", overview = "Maserati: The Brothers, İtalya'nın en köklü ve efsanevi lüks spor otomobil üreticilerinden biri olan Maserati markasının arkasındaki ailenin tutku, rekabet ve başarı dolu hikayesini beyazperdeye taşıyan 2026 yapımı bir biyografik dram filmidir. Oscar ödüllü Bobby Moresco tarafından yönetilen ve yaklaşık 100 milyon dolar gibi dev bir bütçeyle İtalya'da (Modena, Bologna ve Roma'daki Cinecittà Stüdyoları) çekilen yapım, Ferrari ve Lamborghini gibi devlerin yükseldiği dönemde Maserati kardeşlerin küresel bir imparatorluk kurma sürecine odaklanıyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/maserati-the-brothers.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/maserati-the-brothers-izle/", category = "Film"),
