    Movie(id = 1100044, title = "Kıyma: Hain Eşer Kendi Düşer", overview = "Kıyma: Hain Eşer Kendi Düşer izle Kıyma: Hain Eşer Kendi Düşer 2026 Konusu Nedir? Kıyma: Hain Eşer Kendi Düşer Neden İzlenmeli? Kıyma: Hain Eşer Kendi Düşer Hangi Platformda ve Nasıl İzlenir? Kıyma: Hain Eşer Kendi Düşer IMDb Puanı ve Oyuncuları Uzun uğraşlar sonucunda köyüme vardım kanka bir de baktım köyümün meydanında film çekiyorlar bugün bu film karşıma tekizle.com sayesinde birden çıkıverdi acaba bende çıktım mı ekranda diye merak ettim kanka. Kanka, \"Adana sıcağından daha hararetli bir mafya hesaplaşması izleyeyim\" diye…", poster = "https://rfilmizle.com/wp-content/uploads/2026/06/kiyma-hain-eser-kendi-duser.jpg", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/kiyma-hain-eser-kendi-duser-izle/", category = "Film"),
    Movie(id = 1100045, title = "Coyote Acme’ye Karşı-Coyote vs. Acme", overview = "Tüm dünya Coyote’u bir \"kaybeden\" olarak görürken, şanssız bir avukat onun ardındaki haklı mücadeleyi fark eder. İki dışlanmış figürün yolları kesiştiğinde, sadece bir hukuk savaşı değil, aynı zamanda güçlü bir güven bağı kurulur. Davayı kazanmak kadar birbirlerine olan inançlarını korumak da ana hedef haline gelir. Dostluğun ve dayanışmanın gücü, dev şirketlerin parasından ve nüfuzundan çok daha üstün gelir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/07/coyote-vs-acme.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/coyote-vs-acme-izle/", category = "Film"),
    Movie(id = 1100046, title = "Kötü Ruh: Cehennem Ateşi-Evil Dead Burn", overview = "Korkunç bir trafik kazasında eşi Will'i kaybeden Alice, derin bir yas sürecine girer ve acısını hafifletmek amacıyla eşinin ailesinin şehirden uzak, ıssız malikanesine sığınır. Will'in kardeşi Joseph'ın da aralarına katılmasıyla aile yaralarını sarmaya çalışırken, Alice evde kadim ve lanetli Ölüler Kitabı’nın (Necronomicon) bir kopyasını keşfeder. Çaresizlik ve kederin etkisiyle kitapta yer alan tehlikeli ritüelleri tetikleyen aile, farkında olmadan karanlık ve iblisi güçleri serbest bırakır. Huzur aradıkları bu sığınak, aile üyelerinin birer birer vahşi Deadite'lara dönüşmesiyle çok geçmeden kanlı ve klostrofobik…", poster = "https://rfilmizle.com/wp-content/uploads/2026/07/kotu-ruh-cehennem-atesi.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/kotu-ruh-cehennem-atesi-izle/", category = "Film"),
    Movie(id = 1100047, title = "Winchester: Gizemli Ev", overview = "Winchester Tüfekleri servetinin varisi Sarah Winchester (Helen Mirren), San Francisco'nun 50 mil dışında, izole bir arazi üzerinde malikanesinin yapımına başlar ve yıllarca, haftanın 7 günü, günün 24 saati boyunca tadilatlar durmaksızın devam eder. Nihayetinde Winchester Malikanesi devasa bir hale gelir. Dışarıdan bakıldığında çıkmaz koridorlar, karmaşık odalar, labirentler ve boş duvarlara açılan kapılarla tamamen bir kadının deliliği olarak algılanmaktadır. Ama Sarah bu devasa kaosu kendisi için kurmamıştır. Başarılı bir doktor olan yeğeni Eric Price'ı (Jason Clarke) evine davet eden Sarah'nın bir…", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/winchester-gizemli-ev.jpg", backdrop = "", year = "2018", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/winchester-gizemli-ev-izle/", category = "Film"),
    Movie(id = 1100048, title = "Yakın Koruma", overview = "Close, zengin bir mirasçıyı korumakla görevlendirilen terörle mücadele uzmanı olan Sam’in hikayesini konu ediyor. Genç bir kadın olan Sam, başarılı bir terörle mücadele uzmanıdır. Ancak o, kendisine verilen yeni görevi bu zamana kadar yaptığı işlere göre oldukça kolay bulur. Zengin bir iş adamı vefat edince şirketin başına onun genç kızı Zoe geçer. Tüm gözler artık Zoe’nin üzerindedir. Bu yüzden Sam, genç varisi korumakla görevlendirilir. Sam, yeni görevini basit bir iş olarak görse de çok geçmeden Zoe saldırganların hedefi haline gelir.…", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/yakin-koruma.jpg", backdrop = "", year = "2019", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/yakin-koruma-izle-2/", category = "Film"),
    Movie(id = 1100049, title = "Across The Universe – Seni İstiyorum", overview = "Liverpool'dan yola çıkıp kayıp babasını aramak üzere New York'a giden Jude, yolunun Lucy ile kesişmesi üzerine, kendini savaş karşıtı protestoların ve rock'n roll temelli bir hayatın ortasında bulur. Jude'un kardeşi Max'in Vietnam'a gitmesi çifti üzerinde dolaştıkları pembe buluttan indirip başka gerçekleri keşfetmeye zorlar. Bu gerçekler dünyaya bakış açılarını değiştirecektir. Beatles'ın 33 şarkısından yola çıkılarak hazırlanmış bir aşk hikâyesi. Yapım klasik romantik filmlerin izinden gitmek yerine; aşkın gözüyle düzeni sorguluyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/seni-istiyorum.jpg", backdrop = "", year = "2007", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/seni-istiyorum-izle/", category = "Film"),
    Movie(id = 1100050, title = "Son Darbe", overview = "Film, eski bir askerin bir futbol müsabakası sırasında stadı ele geçiren teröristleri durdurmaya çalışması konu ediliyor. Eski bir asker olan Michael Knox, yeğeni ile birlikte maç izlemek için West Ham Stadyumu’na gider. Tuttukları takımı desteklemeye giden ikili oldukça heyecanlıdır. Fakat maçın başlamasının ardından aldığı telefon kendisinin ve statta bulunan insanların hayatını kabusa çevirir. Telefonun ucundaki teröristler stadyumu kontrolleri altına aldıklarını ve dediklerini yapmazlarsa patlatacaklarını söyler. Üstelik bu sırada Michael’ın yeğenini kaçırmışlardır. Teröristler, Michael’ın yeğenini serbest bırakma karşılığında yüklü miktarda fidye…", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/son-darbe.jpg", backdrop = "", year = "2018", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/son-darbe-izle/", category = "Film"),
    Movie(id = 1100051, title = "Naissance des pieuvres Nilüferler", overview = "Floriane yüzme takımı üyesi, alımlı, sarışın ve mükemmel vücutlu bir kız. Küçük ve erkeksi olan Marie içe dönük ve utangaç. Gözlemlemeyi sevenlerden. Anne’in ise kilo problemi var ve biraz dertli ama aynı zamanda lafını esirgemeyen ve dışa dönük bir tip. Anne, gözleri Floriane’dan başkasını görmeyen bir erkek yüzücüye “abayı yakmış”. Bu üç kızın arasındaki ilişki, duyguların yüzme havuzunun ışıltılı ve kuralcı ortamından soyunma odalarının ve yatak odalarının kişisel alanına geçip, arzunun ve kıskançlığın karanlık dehlizlerinde dolaşmaya başlamalarıyla birlikte farklı bir…", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/niluferler.jpg", backdrop = "", year = "2007", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/niluferler-izle/", category = "Film"),
    Movie(id = 1100052, title = "Katil Köpek Balığı Shark Night 3D", overview = "Ailesinin Louisiana gölündeki bir adada bulunan yazlığına tekneyle giden Sara ve arkadaşları, güneş altında eğlenceli bir hafta sonu geçirmek üzere hemen mayolarını kuşanırlar Ancak yıldız futbol oyuncusu Malik sudan tek kolu kopmuş halde, sendeleyerek çıkınca, adadaki parti havası son bulur Malik'in durumu ciddidir ve tedavi için onu adanın diğer tarafına geçirmek için kaybedecek bir dakikaları yoktur Ufak bir hız teknesiyle yola çıkan üniversiteli arkadaşlar çok geçmeden gölün kocaman ve saldırgan yüzlerce köpekbalığıyla dolu olduğunu anlar...", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/katil-kopek-baligi.jpg", backdrop = "", year = "2011", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/katil-kopek-baligi-izle/", category = "Film"),
    Movie(id = 1100053, title = "Corgi – The Queen’s Corgi", overview = "\"The Queen's Corgi\", İngiliz hükümetinin en sevilen köpeği Rex’in maceralarını anlatıyor. Buckingham Sarayı’nda lüks bir yaşam süren şımarık köpek Rex, birbirinden farklı türlerdeki köpeklerle savaşmak zorunda kalır. Ben Stassen'ın yönetmen koltuğunda oturduğu filmin senaryosunu Rob Sprackling, Johnny Smith kaleme alıyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/corgi.jpg", backdrop = "", year = "2019", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/corgi-izle/", category = "Film"),
