    Movie(id = 1100067, title = "Aşka Düşmek", overview = "İşini ve erkek arkadaşını kaybetmesinin ardından, şehirli Gabriela (Christina Milian) spontane şekilde bir yarışmaya katılır ve Yeni Zelanda kırsalında bir pansiyon kazanır. Binlerce kilometre yol katedip kazandığı pansiyona geldiğinde, Bellbird Valley Farm'ın dış cephesinin döküldüğünü, ev arkadaşının bir keçi olduğunu ve meraklı komşusunun aslında bu pansiyonda gözü olduğunu keşfeder. Burayı hızlıca yenileyip satmak isteyen Gabriela, tam bir şehirli olarak yaşadığı kültür şokunu eğlenceli bulan Yeni Zelandalı inşaat ustası Jake Taylor (Adam Demos) ile birlikte çalışmaya başlar. Gabriela şimdi bir karar…", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/aska-dusmek.jpg", backdrop = "", year = "2019", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/aska-dusmek-izle-3/", category = "Film"),
    Movie(id = 1100068, title = "Hunter Killer – Katil Avcısı", overview = "George Wallace ve Don Keith'in 2012 yılında çıkan “Firing Point” romanından uyarlanan filmin konusu şöyle: Kuzey Buz Denizi’nin metrelerce altında, Yüzbaşı Joe Glass önderliğindeki bir Amerikan denizaltısı, başka bir Amerikan denizaltısının Rusya’ya karşı gizli bir darbe planladığını ve dünya düzenini tehdit ettiğini öğrenir. Mürettebat ve ülke tehlikedeyken, Yüzbaşı Glass bir grup seçkin deniz komandosuyla birlikte, kaçırılan Rusya başbakanını kurtarmalı ve 3. Dünya Savaşı’na engel olmak için düşman hattına sızmalıdır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/katil-avcisi.jpg", backdrop = "", year = "2018", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/katil-avcisi-izle/", category = "Film"),
    Movie(id = 1100069, title = "Gözcü – The Watcher", overview = "Brannock ailesi, huzurlu bir başlangıç yapmak umuduyla yeni evlerine taşınır. Ancak kısa süre içinde evlerine gizemli mektuplar gelmeye başlaması, çevrelerindeki insanların göründükleri kadar masum olmadığını düşündürür. Aile, tehditlerin ardındaki kişiyi bulmaya çalışırken mahallenin karanlık geçmişiyle yüzleşir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/ee1Aiyt9poE9HR2IN1OEvbrRGkO-1.webp", backdrop = "", year = "2022", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/gozcu-the-watcher-2022/", category = "Dizi"),
    Movie(id = 1100070, title = "Korku Seansı 2 – The Conjuring 2", overview = "Lorraine ve Ed Warren, kötü niyetli ruhların musallat olduğu bir evde dört çocuğunu tek başına büyüten bekâr bir anneye yardım etmek için Kuzey Londra'ya gider.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/korku-seansi-2.jpg", backdrop = "", year = "2016", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/korku-seansi-2-izle/", category = "Film"),
    Movie(id = 1100071, title = "Gizemli Gerçek", overview = "Her olayı titizlikle çözen ekibin içinden yer alan dedektif Jess´in kızı öldürülür ve katili yakalanamaz. Bunu hazmedemeyen ekipten Ray, vaktini yıllarca dolaşıp katili aramakla geçirir. Ancak aradan 13 yıl geçtikten sonra, katilin izini bulur ve bunu ekibiyle paylaşır. Fakat intikam arzusu hiçbirinin düşünmediği bir şekilde planlarına dahil olmuştur.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/gizemli-gercek.jpg", backdrop = "", year = "2015", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/gizemli-gercek-izle/", category = "Film"),
    Movie(id = 1100072, title = "Catane: Son Sınır – Catane", overview = "Romanya’nın kırsalındaki Catane köyünde yaşayan insanlar, yıllardır devlet yardımları sayesinde kurdukları sıra dışı düzeni sürdürmektedir. Ancak başlatılan bir soruşturma bu düzeni tehdit edince köylüler, sistemi alt etmek için mizah, yaratıcılık ve dayanışmayı bir silaha dönüştürür.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/catane-son-sinir.jpg", backdrop = "", year = "2025", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/catane-son-sinir-izle/", category = "Film"),
    Movie(id = 1100073, title = "En Büyük Benim – The Greatest", overview = "Film, Muhammed Ali’nin sıradan bir genç boksörden dünya çapında tanınan bir şampiyona dönüşmesini konu alır. Kariyerindeki önemli karşılaşmaların yanı sıra, inançları ve aldığı tartışmalı kararlarla mücadele ettiği dönemlere de odaklanır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/the-greatest.jpg", backdrop = "", year = "1977", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/the-greatest-izle/", category = "Film"),
    Movie(id = 1100074, title = "Gökyüzünden Gelen – Cuerpo Celeste", overview = "Şili yeni bir çağın eşiğinde dururken, 15 yaşındaki Celeste kendi hayatının eski düzeninin yıkılışına tanıklık eder. Diktatörlüğün geride bıraktığı korkular henüz silinmemiş, demokrasi ise beraberinde yeni bir belirsizlik getirmiştir. Tam da bu kırılgan dönemde yaşadığı sarsıcı bir olay, Celeste’i çocukluğun kıyısından koparır. Sonsuz çöller ve sert okyanuslarla çevrili dünyası bir anda anlamını yitirirken genç kız, hem ülkesinin hem de kendi hayatının değişen haritasında yolunu bulmaya çalışır. Hayatta kalmanın yoluysa onun için, henüz hazır olmadığı bir romantikliğe adım atmaktan geçer.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/cuerpo-celeste.jpg", backdrop = "", year = "2025", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/cuerpo-celeste-izle/", category = "Film"),
    Movie(id = 1100075, title = "Willoughby Ailesi", overview = "Fena hâlde bencil ebeveynlere sahip dört kardeş, onlardan sonsuza dek kurtulmak için bir plan yapar ve kendilerine kusursuz biçimde sorunlu bir aile kurar.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/willoughby-ailesi.jpg", backdrop = "", year = "2020", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/willoughby-ailesi-izle/", category = "Film"),
    Movie(id = 1100076, title = "Eski Evdeki Büyülü Saat", overview = "Ailesinin ölümünün ardından büyücü olan amcasının yanına taşınan Lewis Barnavelt, şimdiye kadar hiç bilmediği bir dünyaya adım atar. Lewis ve yeni ailesinin, ketum bir büyücü olan Isaac Izard tarafından hazırlanmış, dünyanın sonunu getirecek saati bulup durdurmak için büyük bir mücadele vermesi gerekir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/eski-evdeki-buyulu-saat.jpg", backdrop = "", year = "2018", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/eski-evdeki-buyulu-saat-izle/", category = "Film"),
    Movie(id = 1100077, title = "Aile Planı", overview = "Dan Morgan pek çok şeydir: sadık bir koca, sevgi dolu bir baba, ünlü bir araba satıcısı. Kendisi aynı zamanda eski bir suikastçıdır. Geçmişi bugününe yetişince, hiçbir şeyden haberi olmayan ailesini de yanına almak zorunda kalır. ​", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/aile-plani.jpg", backdrop = "", year = "2023", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/aile-plani-izle/", category = "Film"),
    Movie(id = 1100078, title = "Umutlu Noeller Bringing Christmas Home", overview = "2. Dünya Savaşı'ndan kalma eski bir üniformanın cebinde bir aşk mektubu bulan Russell, yazılanların sırrını Noel'den önce çözebilmek için emekli bir binbaşıdan yardım ister.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/umutlu-noeller.jpg", backdrop = "", year = "2023", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/umutlu-noeller-izle/", category = "Film"),
    Movie(id = 1100079, title = "Reviviendo la Navidad Mutsuz Noeller", overview = "Konu özeti yüklenen HTML dosyalarında bulunmuyor. Kaynak sayfayı açabilirsiniz.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/reviviendo-la-navidad.jpg", backdrop = "", year = "2022", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/reviviendo-la-navidad-izle/", category = "Film"),
    Movie(id = 1100080, title = "Fantastik Canavarlar Nelerdir, Nerede Bulunurlar?", overview = "Büyü-hayvanbilimci Newt Scamander 1926 yılında, uzun süredir emek verdiği, dünyanın her yerinden farklı özellikleri olan büyülü canavarları bularak bunları çantasına toplayıp varlıklarını kanıtlamıştır. New York'a yaptığı kısa süreli ziyaret esnasında yanlışlıkla başka birinin çantasını alır ve bu çok güçlü canavarlardan bazıları serbest kalır. Newt burada kalarak canavarları yakalamak, cadı ve büyücüleri öldüren güçlerle savaşmak durumunda kalacaktır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/fantastik-canavarlar-nelerdir-nerede-bulunurlar.jpg", backdrop = "", year = "2016", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/fantastik-canavarlar-nelerdir-nerede-bulunurlar-izle/", category = "Film"),
    Movie(id = 1100081, title = "Noel Next Door Noel Kapı Komşum", overview = "Çalışkan ve bekar bir anne, Noel zamanı komşusuyla sert bir söz düellosuna girer. Noel ruhunu mahvettiğini düşündüğü bu \"huysuz\" komşusuyla sürekli çatışan anne, zamanla bu yanlış anlaşılan adamın aslında göründüğü gibi olmadığını fark eder. Başta nefret ettiği bu komşusu, beklenmedik bir şekilde annenin kalbini çalacaktır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/noel-kapi-komsum.jpg", backdrop = "", year = "2022", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/noel-kapi-komsum-izle/", category = "Film"),
    Movie(id = 1100082, title = "Sessiz Tepe", overview = "Bir çocuğun gizemli hastalığı. Çaresiz bir anne. Terk edilmiş bir kasaba. Genç bir anne olan Rose kızı Sharon'ın gizemli hastalığına çare bulmak istemektedir. Psikiyatrik tedaviyi reddeden Rose kızıyla birlikte, kızının rüyasında sürekli olarak tekrarladığı kasabaya, SILENT HILL'e doğru yola çıkar. Kocası Christopher'ın karşı çıkmasına rağmen Rose, kızının gizemli hastalığının tedavisinin bu gizemli kasabada olduğuna inanmaktadır. Anne kız kasabaya yaklaşırlarken karşılarına bir gölge çıkar ve Rose arabanın kontrolünü kaybeder. Kendine geldiğinde Sharon arabada yoktur. Rose kızını çaresiz bir biçimde ararken karşısına…", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/sessiz-tepe.jpg", backdrop = "", year = "2006", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/sessiz-tepe-izle/", category = "Film"),
    Movie(id = 1100083, title = "Tekne", overview = "Kayığıyla yoğun siste kaybolan bir balıkçı, terk edilmiş bir teknenin güvertesine sığınır. Birazdan baktığında kendi kayığının ortadan kaybolduğunu fark eder. Bu yabancı tekne ile bilinmeyen sularda ilerledikçe, yolculuk daha ve korkutucu bir hal almaya başlayacaktır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/tekne.jpg", backdrop = "", year = "2019", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/tekne-izle/", category = "Film"),
    Movie(id = 1100084, title = "Gutenberg Projesi", overview = "\"Ressam\" kod adlı birinin yönettiği çete sahte para biriminin orijinalliğini ayırt etmeyi zorlaştıran olağanüstü sahte yeteneklere sahiptir. Suç faaliyetlerinin kapsamı küresel çapta yayılır ve polisin dikkatini çeker. Hong Kong polisi “Ressam” ın gerçek kimliğini bulmak , davayı çözmeye yardımcı olmak için Lee Man ' işe alır ve suç dünyasına 'Ressam' olarak yerleştirir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/gutenberg-projesi.jpg", backdrop = "", year = "2018", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/gutenberg-projesi-izle/", category = "Film"),
    Movie(id = 1100085, title = "Efsane Sürücü Trading Paint", overview = "Deneyimli yarış arabası şoförü Sam Munroe ve oğlu, küçük bir kasabadan gelen bir sürücüdür. ikisi birlikte Aile ve mesleki çatışmaların üstesinden gelirken, rekabet, ego, kızgınlık ve diğer tarafta daha güçlü bir şekilde ortaya çıkan bir yarış çarkının içinde bulurlar kendilerini.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/efsane-surucu.jpg", backdrop = "", year = "2019", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/efsane-surucu-izle/", category = "Film"),
    Movie(id = 1100086, title = "Johnny English Tekrar İş Başında (Johnny English Strikes Again)", overview = "Bir siber saldırı sonucu Britanya’daki tüm aktif gizli ajanların kimlikleri ortaya çıkmıştır. Gizli servisin baş hacker’ı bir an önce bulması gerekir. Fakat hiçbir gelişme katedilemeyince gizli servis çareyi bir süre önce emekli olan Johnny English’i geri çağırmakta bulur. Görevi kabul eden English, baş hacker’ı bulmak için kolları sıvasa da bu iş sandığı kadar kolay olmayacaktır. Eski usul yöntemlere sahip olan Johnny English’in hacker’ı bulması için modern teknolojinin zorlukları ile mücadele etmesi gerekir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/johnny-english-tekrar-is-basinda.jpg", backdrop = "", year = "2018", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/johnny-english-tekrar-is-basinda-izle/", category = "Film"),
    Movie(id = 1100087, title = "Saka Kuşu", overview = "Donna Tartt’ın Pulitzer ödüllü, uluslararası çok satan romanı Saka Kuşu’ndan uyarlanmış yapım, yaşanan bir patlama sonrası New York gibi büyük bir şehirde yapayalnız kalan on üç yaşındaki Theodore Decker’ın çocukluğundan romantikliğine, kayıplarla dolu ömrünü anlatıyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/saka-kusu.jpg", backdrop = "", year = "2019", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/saka-kusu-izle/", category = "Film"),
    Movie(id = 1100088, title = "Soğuk Savaş Zimna wojna", overview = "Zula ve Wiktor birbirinden tamamen farklı karakterlere sahip olan iki aşıktır. Her ne kadar birbirleriyle anlaşamayacak tipler olsalar da kader onların yollarını ayrılmayacak şekilde birbirine bağlar. Soğuk Savaş sırasında Polonya’dan Berlin’e, Yugoslavya’dan Paris’in gece kulüplerine uzanan filmde, siyasi görüş, karakter ve kaderin cilvesiyle savrulan Zula ve Wiktor’un tutkulu aşkı ele alınıyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/soguk-savas.jpg", backdrop = "", year = "2018", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/soguk-savas-izle/", category = "Film"),
    Movie(id = 1100089, title = "Karanlıkta (In Darkness)", overview = "Görme engelli bir piyanist olan Sofia'nın hayatı, üst komşusu Veronique'nin şüpheli bir cinayete kurban gitmesiyle altüst olur. Olayın sorumluları, cinayetin tek tanığı olan genç kadının peşine düşerler. Sofia, kendini bir anda acımasız bir suç örgütünün hedefi haline gelmiş halde bulur. Gizli ajanlar, suç ve şantajla örülü yeraltı dünyasında cinayetin perde arkasını çözmeye çalışırken Sofia'nın yolu, Veronique'nin eski bir savaş suçlusu olan babasıyla kesişecektir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/karanlikta.jpg", backdrop = "", year = "2018", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/karanlikta-izle/", category = "Film"),
    Movie(id = 1100090, title = "Parçalanmış – Split", overview = "Güvenilir psikiyatr Dr. Fletcher, Kevin adlı hastasının en az 23 farklı kişiliği bünyesinde barındırdığını kanıtlamıştır. Ancak henüz tamamen ortaya çıkmamış son bir kişilik vardır ki, meydana çıktığında diğer kişilikleri süpürecek çok vahşi bir karakterin habercisidir. Bu dizginlemesi zor gücün etkisiyle Kevin, 3 genç kızı kaçırıp yaşadığı yerde alıkoyar. Hırslı ve kararlı Casey'nin önderliğinde gençler hayatta kalabilmek için, Kevin içindeki şeytani güce tamamen boyun eğmeden önce oradan kaçmak zorundadırlar.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/parcalanmis.jpg", backdrop = "", year = "2017", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/parcalanmis-izle/", category = "Film"),
    Movie(id = 1100091, title = "Mucize (Wonder)", overview = "R.J. Palacio'nun romanından senaryolaştırılan filmde, Auggie Pullman yaşıtı diğer çocuklardan biraz farklıdır. Çünkü yüzünde ciddi bir deformasyon vardır. Auggie diğer çocuklarla sıradan bir okula giderek, sıradan bir çocuk olduğunu annesi Isabel ve babası Nate'in yardımıyla kanıtlamaya çalışır. Çünkü esas güzellik derinin altında, içeride saklıdır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/mucize.jpg", backdrop = "", year = "2017", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/mucize-izle/", category = "Film"),
    Movie(id = 1100092, title = "Aynen Aynen", overview = "Başrollerinde Kerem Bürsin ve Nilperi Şahinkaya’nın yer aldığı bu dizide, hayal kırıklıklarıyla dolu bir ilişkiden çıkan Nil yeni ev arkadaşı Deniz’le eğlence ve aşk dolu maceralara atılıyor! Nil ve Deniz’in birbirlerini tanımaya başladığı bu süreçte hem karşı tarafa kendilerini göstermek istedikleri hallerini hem de aslında kendi gerçek düşüncelerini görüp bu zıtlık karşısında çok eğleniyoruz! Onları izledikçe adeta kendimizi bulabileceğimiz bir dizi!", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/clqQaVbpnrFG7dvpjFA0lX1i5mi-204x300-1.jpg", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/aynen-aynen-1-sezon/", category = "Yerli Diziler"),
    Movie(id = 1100093, title = "Bizden Olur mu?", overview = "İlişkilerinde sürekli hayal kırıklığı yaşayan Deniz ve Sarp, çareyi ilişki tavsiyeleri veren kitaplarda arar. Birbirlerini tanımak için buluştuklarında bu kitaptaki taktikleri uygulamaya çalışırlar. Doğal davrandıklarında harika bir çift olabilecekken, uyguladıkları taktikler yüzünden her buluşmayı adeta bir felakete ve komik durumlara dönüştürürler", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/images-36sh.er_.jpg", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/bizden-olur-mu-1-sezon/", category = "Yerli Diziler"),
