    Movie(id = 1100097, title = "The Snare", overview = "Bir lise öğrencisi az miktarda uyuşturucuyla yakalandığında polis onu muhbir olması için zorlar; bu durum genç kızı en çok sevdiği insanlar ile uğruna çok çalıştığı gelecek arasında bir seçim yapmaya mecbur bırakır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/the-snare.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/the-snare-izle/", category = "Film"),
