    Movie(id = 1100099, title = "The Bluey Movie – Bluey Filmi", overview = "Bluey ve küçük kız kardeşi Bingo, anne ve babalarıyla birlikte unutamayacakları yeni bir maceraya atılır. Oyunlarını gerçek bir serüvene dönüştüren iki kardeş, aile olmanın ve birlikte geçirilen zamanın değerini keşfeder.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/bluey-filmi.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/bluey-filmi-izle/", category = "Film"),
    Movie(id = 1100100, title = "Cesur Kirpi Spiked", overview = "Hayalperest Kirpi Holly, büyük bir tavşan ailesinin parçası olmanın hayalini kurar. Bir gün komik bir tesadüf sonucu, komşusu Walter hafızasını kaybeder. Holly hemen bir macera uydurur: Artık Walter onun babasıdır! Ama Walter kendini bir çizgi roman şövalyesi sanınca, hayal ettikleri serüven çılgınca bir yolculuğa dönüşür. Gerçek aile olmanın yolu, yalanlardan değil, dostluk ve sevgiyle atılan adımlardan geçer.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/cesur-kirpi.jpg", backdrop = "", year = "2025", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/cesur-kirpi-izle/", category = "Film"),
    Movie(id = 1100101, title = "Spaceballs: The New One", overview = "Karanlık Miğfer, aradan geçen yılların ardından intikam için geri döner. Galaksiyi koruyabilecek güç giderek azalırken Prens Starburst, efsanevi Lone Starr'ın izini sürer. Ancak eski kahramanları bulduklarında, karşılarındaki tehdidin savaşarak çözülemeyecek kadar büyük olduğunu keşfederler.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/spaceballs-the-new-one.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/spaceballs-the-new-one-izle/", category = "Film"),
    Movie(id = 1100102, title = "The Garfield Movie 2 – Garfield 2: İki Kedinin Hikayesi", overview = "Garfield, Odie ve babası Vic'in hayatı, beklenmedik bir macerayla yeniden altüst olur. Rahat yaşamını ve bol lazanyalı günlerini geride bırakmak zorunda kalan Garfield, bu kez ailesini korumak için istemeden büyük bir maceranın içine atılır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/the-garfield-movie-2.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/the-garfield-movie-2-izle/", category = "Film"),
    Movie(id = 1100103, title = "CoComelon: The Movie", overview = "JJ ve yakın arkadaşları, onları evlerinden çok uzaklara götürecek yepyeni bir maceraya atılır. Karşılarına çıkan beklenmedik sorunları birlikte çözmeye çalışırken dostluğun ve dayanışmanın önemini keşfederler.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/cocomelon-the-movie.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/cocomelon-the-movie-izle-2/", category = "Film"),
    Movie(id = 1100104, title = "Witch on the Holy Night – Mahôtsukai no Yoru", overview = "Eski ve gizemli bir malikânede tek başına yaşayan bir cadı, bir gün iki genç çırağı yanına alır. Başlangıçta sessiz ve kurallarla dolu olan hayatı, öğrencilerinin merakı ve enerjisiyle tamamen değişir. Zamanla cadı, yıllardır kapattığı dünyasının yeniden canlandığını fark eder.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/e9ad94e6b395e4bdbfe38184e381aee5a49c.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/%e9%ad%94%e6%b3%95%e4%bd%bf%e3%81%84%e3%81%ae%e5%a4%9c-izle/", category = "Film"),
    Movie(id = 1100105, title = "Somebody.", overview = "Yüzme eğitmeni Young-eun, 7 yaşındaki kızı So-hyun'u tek başına büyüten bir annedir. Ancak, So-hyun'un köpeğinin apartmandan düşüp ölmesi ve So-hyun'un okulda diğer çocuklara zorbalık yapması gibi bir dizi trajik olay yaşanır. Annesinin So-hyun'un ruhsal bozukluğunu gidermek için gösterdiği tüm çabalara rağmen, kızın tuhaf davranışları devam eder. Yirmi yıl sonra, sahipsiz ölümlerle ilgilenen Min, yeni bir meslektaşı olan Hae-young ile tanışır ve aralarında yakın bir bağ oluşur. Ancak, Hae-young kendini Min'in hayatına sıcak bir şekilde entegre ederken, Min onun niyetleri konusunda…", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/somebody.jpg", backdrop = "", year = "2025", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/somebody-izle/", category = "Film"),
