    Movie(id = 1100107, title = "Werwulf", overview = "1305 yılında İngiltere'nin ücra bir köyünde yaşayan sessiz bir çiftçi, ailesiyle huzurlu bir hayat kurmaya çalışır. Ancak her dolunayda korkunç bir yaratığa dönüşmesi, sakladığı sırrı giderek daha tehlikeli hale getirir. Kralın gönderdiği avcılar köye geldiğinde, hem ailesini korumak hem de içindeki canavarla mücadele etmek zorunda kalır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/werwulf.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/werwulf-izle/", category = "Film"),
