    Movie(id = 1100111, title = "Just Play Dead Sadece Ölü Taklidi Yap", overview = "Bir suçlu, sigorta parasını almak için ölümünü taklit etmeyi ve suçu karısının sevgilisinin üzerine atmayı planlar. Karısı ise onu gerçekten öldürüp tüm parayı ele geçirmeyi amaçlar. İkisi de ölümcül bir zekâ savaşına girer ve birbirlerini alt etmeye çalışırlar.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/just-play-dead.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/just-play-dead-izle/", category = "Film"),
