    Movie(id = 1100113, title = "Vahşi Orman – Wildwood", overview = "Prue McKeel'in küçük kardeşi bir gün gizemli bir karga sürüsü tarafından kaçırılır. Onu bulmak için Oregon'un ötesindeki büyülü ve tehlikeli ormana giren Prue'ya sakar ama sadık sınıf arkadaşı Curtis eşlik eder. İkili, konuşan hayvanlar ve güçlü düşmanlarla karşılaşırken kardeşini kurtarmanın sandıklarından çok daha büyük bir mücadele olduğunu keşfeder.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/vahsi-orman.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/vahsi-orman-izle/", category = "Film"),
