    Movie(id = 1100118, title = "Klara ve Güneş – Klara and the Sun", overview = "İnsanların yalnızlığını gidermek için tasarlanan yapay zekâlı bir robot kız olan Klara, kırılmış bir ailenin hayatına girer. Aileyi yeniden bir araya getirmeye çalışırken insan duygularını gözlemlemeye başlayan Klara, sevgi ve bağlılığın sandığından çok daha karmaşık olduğunu keşfeder.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/klara-and-the-sun.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/klara-and-the-sun-izle/", category = "Film"),
    Movie(id = 1100119, title = "Your Mother Your Mother Your Mother – Annen Annen Annen", overview = "Dindar ve profesyonel bir tetikçi olan Latif, eşinin ani ölümünün ardından çocuklarını korumak için Houston'ın tehlikeli sokaklarında zorlu bir yolculuğa çıkar. Peşindeki güçler giderek yaklaşırken Latif, ailesini kurtarmak için hem düşmanlarıyla hem de sarsılmaya başlayan inancıyla yüzleşir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/your-mother-your-mother-your-mother.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/your-mother-your-mother-your-mother-izle/", category = "Film"),
    Movie(id = 1100120, title = "Easy Girl Smalltown Girl Küçük Kasaba Kızı", overview = "Özgür ruhlu ve baştan çıkarıcı bir kadın olan Nore, eski sınıf arkadaşı ve çalışkan öğrenci Jonna ile aynı eve taşınır. Birbirinden önemsiz erkeklerle yaşadıkları kaygısız tek gecelik ilişkiler sırasında, Nore'un derinden sorunlu geçmişinin mutluluğun önünde bir engel olduğunu fark ederler.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/smalltown-girl.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/smalltown-girl-izle/", category = "Film"),
    Movie(id = 1100121, title = "Gaskins: The Hitchhiker Killer", overview = "Gerçek olaylardan uyarlanan Gaskins: Otostopçu Katil, Güney Carolina'nın en kötü şöhretli seri katili Donald \"Pee Wee\" Gaskins'in geçmişinin peşini bırakmaması ve 1960'lardan 1980'lere uzanan acımasız bir hesaplaşmayla imparatorluğunun nasıl yıkıldığını konu alıyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/gaskins-the-hitchhiker-killer.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/gaskins-the-hitchhiker-killer-izle/", category = "Film"),
