    Movie(id = 1100135, title = "İki Tez Arasında", overview = "rakamlara, verilere ve ekonomik gerçeklere önem veren iktisat öğrencisi Metin ile doğayı ve ekosistemi savunan idealist çevreci Ela bulunuyor. Üniversitede karşı karşıya gelen ikilinin serüveni, maden ocaklarına yaptıkları yolculukla farklı bir boyut kazanıyor. Bergama Altın Madeni çevresindeki köylerde incelemelerde bulunan Ela, dört altın madenini gezerek konuya ilişkin bilgilerini gözden geçirirken, Metin de çevrecilerin altın madenleri üzerindeki etkisine tanıklık ediyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/iki-tez-arasinda.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/iki-tez-arasinda-izle/", category = "Film"),
