    Movie(id = 1100140, title = "Ceza", overview = "Mahnaz, 40 yaşında, dul bir hemşiredir. Okuldan uzaklaştırılan asi oğlu Aliyar'la baş etmeye çalışmaktadır. Yeni erkek arkadaşı Hamid'le yapılan nişan töreni sırasında aile içindeki gerilim doruğa ulaşır ve trajik bir kaza yaşanır. Bu olayın ardından Mahnaz, ihanet ve kayıpla yüzleşmek zorunda kalacak ve adalet arayışına çıkacaktır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/ceza.jpg", backdrop = "", year = "2025", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/ceza-izle/", category = "Film"),
