    Movie(id = 1100144, title = "Untold Mr. T: I Pity the Fool", overview = "Altın zincirleri, mohawk saç modeli ve A-Team ile Rocky III'ün Hollywood şöhretinden önce, Laurence Tureaud vardı. Bu, eğlence dünyasının en beklenmedik ve sevilen ikonlarından biri olan Mr. T.'nin sıra dışı köken öyküsüdür.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/untold-mr-t-i-pity-the-fool.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/untold-mr-t-i-pity-the-fool-izle/", category = "Film"),
