    Movie(id = 1100147, title = "Mahsun J", overview = "İstanbul'da büyük bir borç yükü altında ezilen ve geçimini motokuryelik yaparak sağlayan Mahsun'un hikayesini anlatır. Arkadaşının yerine gittiği bir paket teslimatı sırasında hayatı tamamen değişen Mahsun, borçlarından kurtulmak ve yeni bir çıkış yolu bulmak için sıra dışı bir \"ek gelir\" kapısı keşfederek jigolo olmaya karar verir. Bu yeni dünyada arkadaşı Leyla ile birlikte yaşadığı maceralar, arkadaşlık, cesaret ve hırs temaları üzerinden mizahi bir dille işlenir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/29398294-85792546-239x300-1.webp", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/mahsun-j-1-sezon/", category = "Yerli Diziler"),
    Movie(id = 1100148, title = "Masum", overview = "Emekli Komiser Cevdet ve karısı Nermin, ömürlerinin son yıllarını şehirden uzakta, sakin bir çiftlik evinde huzur içinde geçirmektedir. Ancak küçük oğullarının bir gece yarısı korkunç bir haberle eve gelmesiyle, aile şoke edici sırlarla dolu gizemli bir cinayetin tam ortasına çekilir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/images-36ddd-2.jpg", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/masum-1-sezon/", category = "Yerli Diziler"),
    Movie(id = 1100149, title = "Pavyon", overview = "Pavyonlar, Ankara eğlence sektörünün yaklaşık %80'ini karşılamasına ve il ekonomisini kayda değer bir biçimde beslemesine rağmen, efsaneleşmiş klişelerin yarattığı söylemler sebebiyle genişçe bir kısım tarafından kabul görmez. Konsomatrisler, müdavimler, yalnızlar, âlemciler, işletmeciler, bolca neon ışık, kabarık hesaplar. Ülkenin bir kesimince \"tabu\" olarak kabul gören pavyon kültürü, seride etraflıca ele alınıyor.", poster = "https://rfilmizle.com/wp-content/themes/filmplus/images/no-thumbnail.png", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/pavyon-1-sezon/", category = "Yerli Diziler"),
    Movie(id = 1100150, title = "Prens", overview = "Türkiye'nin ilk sanal stüdyo (Virtual Production) ortamında çekilen bu sezonda, kimsenin adını bile koymaya tenezzül etmediği ortanca prensin, Bongomia Krallığı'nı birbirine katışına ve taht mücadelesine tanık oluyoruz", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/72306674-92386922-210x300-1.webp", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/prens-1-sezon/", category = "Yerli Diziler"),
    Movie(id = 1100151, title = "Çıplak", overview = "Eylül babaannesi ile birlikte yaşamakta ve geçimini eskortluk yaparak kazanmaktadır. Bir gece Instagram üzerinden onu bulan bir arkadaş grubunun bekarlığa veda partisine çağırılır. Eylül, sosyetik bir kızla evlenmek için gün sayan müstakbel damat Cem’e aşık olur. Cem de Eylül’den etkilenir. O geceden sonra Cem ve Eylül’ün hayatları birbirine karışmaya başlar.", poster = "https://rfilmizle.com/wp-content/themes/filmplus/images/no-thumbnail.png", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/ciplak-1-sezon/", category = "Yerli Diziler"),
    Movie(id = 1100152, title = "Truly Naked", overview = "Babasının şirketinde çalışırken yalnızca kameranın arkasından yakınlık deneyimlemiş, içine kapanık bir genç, cesur bir sınıf arkadaşının onu gerçek bağlantıyı kucaklamaya teşvik etmesiyle kameranın arkasından çıkmak zorunda kalır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/73621333-14955107-220x300-1.webp", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/truly-naked-izle/", category = "Film"),
