    Movie(id = 1100154, title = "Tony", overview = "19 yaşındaki Anthony Bourdain, Massachusetts eyaletinin Provincetown kasabasına gider. Kaotik bir restoran mutfağında çalışmaya başlar. Bu yaz dönemi, onun hayatının yönünü değiştirir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/tony.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/tony-izle/", category = "Film"),
    Movie(id = 1100155, title = "Kyma, l’onde mystérieuse", overview = "Küçük bir köyde, hayvanlara tutkuyla bağlı, içine kapanık bir genç olan Tony'nin hayatı, maddeyi parçalayabilen canlı bir ses dalgası olan olağanüstü bir yaratık keşfettiğinde altüst olur. İki arkadaşının yardımıyla onu evcilleştirmeye çalışır. Ancak kısa süre sonra, gizli bir örgütün de bu uzaylı varlığı yakalamaya çalıştığını fark ederler.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/kyma-londe-mysterieuse.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/kyma-londe-mysterieuse-izle/", category = "Film"),
    Movie(id = 1100156, title = "Saygı", overview = "Saygı Dizisi Konusu: SAYGI – ‘Bir Ercüment Çözer Dizisi’, Behzat Ç. - “Bir Ankara Polisiyesi” dizisinin anti-kahramanı olan Ercüment Çözer’in hayatına odaklanıyor. Toplumun yozlaşmasına karşı kendi adalet sistemini uygulayan Ercüment Çözer'in hayatı, kendisi ile aynı amaca yönelik hareket ettiğini düşündüğü iki genç ile tanıştığında bambaşka bir hal alır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/Saygi-211x300-1.webp", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/saygi-1-sezon/", category = "Yerli Diziler"),
    Movie(id = 1100157, title = "Yarım Kalan Aşklar", overview = "İdealist ve gözü kara bir gazeteci olan Ozan, kendisi gibi gazeteci olan sevgilisi Elif ile evlenmek üzeredir. Ancak Ozan, peşinde olduğu gizemli ve tehlikeli bir haber yüzünden geçirdiği şüpheli bir trafik kazasında hayatını kaybeder. Fakat Ozan için her şey bitmemiştir; başka bir bedende, sorumsuz ve hayatı altüst olmuş cinayet büro komiseri Kadir'in bedeninde yeniden dünyaya döner.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/3511651-49210268-210x300-1.jpg", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/yarim-kalan-asklar-1-sezon/", category = "Yerli Diziler"),
    Movie(id = 1100158, title = "Yeşilçam", overview = "Yeşilçam Dizisi Konusu: 1960’lar Türkiye’sinin gölgesinde, altın çağını yaşamaya başlayan Yeşilçam’da bir yapımcının ayakta kalma hikâyesini anlatan Yeşilçam: Bir Sinema Hayvanı’nda Çağatay Ulusoy, her şeyini kaybetmiş ancak Yeşilçam’da küllerinden yeniden doğmaya çalışan sinema aşığı yapımcı Semih Ateş’e hayat veriyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/Yesilcam.jpg", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/yesilcam-1-sezon/", category = "Yerli Diziler"),
    Movie(id = 1100159, title = "İlk ve Son", overview = "Deniz ve Barış, 20’li yaşlarında tanışıp birbirlerine aşık olmuş iki gençtir. Seneler içinde ilişkileri büyük yaralar alır, ancak aşkları sayesinde bir şekilde birbirlerine tutunmaya çalışır, birlikteliklerine devam etmeyi başarırlar. Ta ki birlikte büyümenin ve değişmenin yarattığı sancılar, onları artık birbirleriyle kalamayacak - ve birbirlerini tanıyamayacak - kadar yıpratana kadar.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/17370209-12628080-300x300-1.webp", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/ilk-ve-son-1-sezon/", category = "Yerli Diziler"),
    Movie(id = 1100160, title = "Çekiç ve Gül: Bir Behzat Ç. Hikayesi", overview = "Cinayet Büro'da görev yapan polis Behzat Ç.'nin hayatına değinecek olan yapımda polistir. Aldığı kıdem tenzilleri nedeniyle başkomiser olan Behzat Ç. ve ekibi başkent Ankara'da işlenen cinayetleri çözmeye çalışacaklar.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/Cekic-ve-Gul-Bir-Behzat-C.-Hikayesi-210x300-1.webp", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/cekic-ve-gul-bir-behzat-c-hikayesi-1-sezon/", category = "Yerli Diziler"),
    Movie(id = 1100161, title = "A Mosquito in the Ear", overview = "Amerikalı bir çift, yeni evlat edindikleri dört yaşındaki kızlarını eve getirmek için Goa'ya gelir ve ailesi olmanın ikisinin de hazırlıklı olmadığı bir yolculuk olduğunu keşfeder.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/a-mosquito-in-the-ear.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/a-mosquito-in-the-ear-izle/", category = "Film"),
    Movie(id = 1100162, title = "Maya & Samar", overview = "Çağdaş Atina'da geçen Maya ve Samar, kısa ama ateşli ilişkileri birinin hayatını tehlikeye atarken diğerini anında çevrimiçi şöhrete iten, çatışan kültürlerden iki genç kadının hikayesini anlatıyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/maya-samar.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/maya-samar-izle/", category = "Film"),
    Movie(id = 1100163, title = "Portal to Hell", overview = "Woody Bess tarafından yönetilen ve başrolünde Trey Holland ile Keith David'in yer aldığı 2025 yapımı korku-komedi filmi kastediliyorsa, film Türkiye'deki dijital platformlarda genellikle orijinal adı olan \"Portal to Hell\" şeklinde veya doğrudan çevirisiyle listelenmektedir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/portal-to-hell.jpg", backdrop = "", year = "2025", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/portal-to-hell-izle/", category = "Film"),
    Movie(id = 1100164, title = "Damalı Ninja 3", overview = "Film, Aske'nin ninja maceralarına olan ilgisinin azalması ve Kareli Ninja'nın kendini dışlanmış hissederek yeni bir görev istemesiyle başlar. Aske, tesadüfen Jessica'nın serseri erkek arkadaşı Marco ile çatışmaya girer. Ninja, onu kendisini savunmaya zorlayarak tehlikeli olayların fitilini ateşler.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/damali-ninja-3.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/damali-ninja-3-izle/", category = "Film"),
