    Movie(id = 1100166, title = "Julie Zwijgt Julia Sessiz", overview = "Seçkin bir tenis akademisinin yükselen yıldızı Julie'nin tüm yaşamı tenis üzerine kuruludur. Ancak antrenörü hakkında açılan soruşturmanın ardından görevden alınmasıyla kulüpteki tüm sporcular yaşananları anlatmaya davet edilir. Julie ise bildiklerini paylaşmak yerine sessiz kalmayı seçer.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/julia-sessiz.jpg", backdrop = "", year = "2024", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/julia-sessiz-izle/", category = "Film"),
    Movie(id = 1100167, title = "Sen, Ben ve Toscana (You, Me & Tuscany)", overview = "Anna, şef olma hayallerinden vazgeçmiş ve yirmili yaşlarında bir dizi kötü tercihle boğuşan genç bir kadındır. Anna, ev bakıcılığı işini bir anda kaybettiğinde, Toskana'da boş bir villası olan yakışıklı İtalyan Matteo ile şans eseri karşılaşması, her zaman dürüst olan en yakın arkadaşı Claire'in tavsiyelerine rağmen İtalya'ya uçmasına ilham verir. Ancak Anna'nın, Matteo'nun villasında izinsiz bir gece geçirme planı, Matteo'nun annesi beklenmedik bir şekilde eve gelince suya düşer. Panik içinde Anna, Matteo'nun nişanlısı olduğuna inanmasına izin verir. Ancak bu küçük yalan,…", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/sen-ben-ve-toscana.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/sen-ben-ve-toscana-izle/", category = "Film"),
    Movie(id = 1100168, title = "Maxton Hall – Aramızdaki Dünya", overview = "Mütevazi bir aileden gelen burslu öğrenci Ruby Bell, Maxton Hall özel okulunda yanlışlıkla büyük ve sarsıntılı bir sırra şahit olur. Bu durum onu zengin ve kibirli milyarder mirasçı James Beaufort'un hedefi haline getirir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/images-36ddd.jpg", backdrop = "", year = "", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/maxton-hall-aramizdaki-dunya-1-sezon/", category = "Dizi"),
    Movie(id = 1100169, title = "Influence", overview = "Akıl sağlığı sorunlarıyla boğuşan bir film yapımcısı, sabrının sonuna gelir ve son projesinde başrolü oynaması için ünlü bir sosyal medya fenomenini kaçırır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/influence.jpg", backdrop = "", year = "2023", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/influence-izle/", category = "Film"),
    Movie(id = 1100170, title = "Dört Geçiş – Si du – Crossing", overview = "Mao Zedong, Kızıl Ordu'yu yöneterek Çişui Nehri'ni dört kez geçti ve savaş tarihinde klasik bir savaş örneği ve gerilla savaşının efsanesini yarattı.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/e59b9be6b8a1.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/%e5%9b%9b%e6%b8%a1-izle/", category = "Film"),
    Movie(id = 1100171, title = "Beauty From Surrender Teslimiyetten Doğan Güzellik", overview = "İlk filmde Avustralya'da geçirdikleri tutkulu üç aydan sonra, Jack'in \"iletişim yok\" kuralı üzerine Laurelyn ülkeyi büyük bir kalp kırıklığıyla terk eder. Jack'in kendisine karşı hiçbir şey hissetmediğine ikna olan Laurelyn, Nashville'e geri döner ve acısını unutmak için tek hayali olan müziğe sığınır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/images-36.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/beauty-from-surrender-teslimiyetten-dogan-guzellik-2026/", category = "Film"),
    Movie(id = 1100172, title = "Kötü Kedi Şerafettin 2", overview = "Şero, Fare Rıza ve Martı Rıfkı gibi efsane Cihangir ekibinin, sokağın kendine has dili ve absürt maceralarıyla geri dönmesi bekleniyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/17158116-23261829-300x225-1.webp", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/izle/", category = "Film"),
    Movie(id = 1100173, title = "Blue Lock", overview = "Japonya Futbol Federasyonu'nun Dünya Kupası'nı kazanmak amacıyla Jinpachi Ego önderliğinde başlattığı sıra dışı bir projeyi konu alır. Japonya'nın en iyi ve en bencil forvetini yaratmak için 300 genç yetenek \"Mavi Kilit\" (Blue Lock) adlı yüksek teknolojili bir tesise kapatılır. Buradan elenen oyuncular, hayatları boyunca bir daha Japonya Milli Takımı'nda oynayamama cezasıyla karşı karşıya kalırlar", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/e38396e383abe383bce383ade38383e382af.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/%e3%83%96%e3%83%ab%e3%83%bc%e3%83%ad%e3%83%83%e3%82%af-izle/", category = "Film"),
    Movie(id = 1100174, title = "Before The Ice Melts Buz Erimeden Önce", overview = "Yetenekli bir kadın buz hokeyi oyuncusu, profesyonel olarak oynamak hayalini gerçekleştirmek için bir takım tarafından transfer edilip edilmeyeceğini heyecanla bekliyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/before-the-ice-melts.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/before-the-ice-melts-izle/", category = "Film"),
    Movie(id = 1100175, title = "The Militia Milisler", overview = "Daniel Pierce, yerel bir milisle birlikte papazına başvurdu. Ancak pederiniz yerel şerifin hedefine teslim olduğunda Daniel ve dostları, kurtarıcı tarafından çalkantılı bir şekilde milisleri eğitmeye başlar.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/the-militia.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/the-militia-izle/", category = "Film"),
    Movie(id = 1100176, title = "Pohádky po babicce Tales from the Magic Garden", overview = "Üç çocuk, büyükannelerini, yani ailenin hikaye anlatıcısını kaybettikten sonra oluşan sessizliği doldurmak için büyükbabalarının evinde bir gece geçirirler. Kendi hikayelerini yaratırlar ve hayal gücünün gücünü keşfederler.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/pohadky-po-babicce.jpg", backdrop = "", year = "2025", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/pohadky-po-babicce-izle/", category = "Film"),
    Movie(id = 1100177, title = "Hot Spot", overview = "Gelecekteki, bilinçli yapay zekâların hüküm sürdüğü bir dünyada işlenen bir cinayeti araştıran özel dedektifin kimliği ve evliliği hipnotik bir çöküşe uğrar.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/hot-spot.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/hot-spot-izle/", category = "Film"),
    Movie(id = 1100178, title = "Tarung: Unforgiven", overview = "Hatta, bir silat müsabakasında rakibinin ölümüne kazara sebep olduktan sonra travma geçiren ve vicdan azabıyla boğuşan eski bir silat şampiyonudur.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/tarung-unforgiven.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/tarung-unforgiven-izle/", category = "Film"),
    Movie(id = 1100179, title = "The Mosquito Bowl", overview = "Pearl Harbor saldırısından sonra şöhretlerini bir kenara bırakıp ABD Deniz Piyadeleri'ne katılan dört Amerikan futbolu yıldızının ve Okinawa Muharebesi öncesinde oynadıkları efsanevi maçın gerçek hikayesini anlatır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/the-mosquito-bowl.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/the-mosquito-bowl-izle/", category = "Film"),
    Movie(id = 1100180, title = "Benimle Kal Remain", overview = "New Yorklu mimar Tate Donovan, en yakın arkadaşının yazlık evini tasarlamak için Cape Cod'a gider. Yakın zamanda akut depresyon tedavisi gördüğü bir psikiyatri kliniğinden serbest bırakılmasının ardından yeni bir başlangıç ​​aramaktadır. Hala çok sevdiği kız kardeşini kaybetmenin acısıyla boğuşan Donovan, Wren adında genç bir kadınla tanışır ve bu kadın, onun dünyasıyla ilgili bildiği her şeyi sorgulamasına neden olur.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/yRKZSwJopvHzfWNFxUrCzLQgcrK.webp", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/remain-izle/", category = "Film"),
    Movie(id = 1100181, title = "Paw Patrol: Dino Filmi (PAW Patrol: The Dino Movie)", overview = "Backstreet Boys'un film için hazırladığı özel \"Bottle Up\" şarkısının melodileriyle süslenen yapım, animasyon kalitesinde zirveyi hedefliyor. Tropik adanın göz alıcı renk paletleri, devasa yanardağ patlamasının yarattığı partikül efektleri ve seslendirme kadrosundaki Mckenna Grace, Terry Crews, Snoop Dogg ve Paris Hilton gibi dünya yıldızlarının performansları birleşiyor. Sinemaseverlere hem işitsel hem de görsel olarak unutulmaz bir animasyon şöleni vadediliyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/paw-patrol-dino-filmi.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/paw-patrol-dino-filmi-izle/", category = "Film"),
