    Movie(id = 1100183, title = "Kutudaki Koyun Sheep in the Box", overview = "Yakın gelecekte geçen bu hikâyede bir mimar olan Otone Komoto, bir inşaat şirketi işleten Kensuke Komoto ile evlidir. Bu evli çift, evlerine yakın zamanda kaybettikleri oğulları Kakeru'ya benzeyen insansı bir robotu evlerine kabul etmeye karar verir. Film, duygusal ve etik karmaşıklıkları, yas, teknoloji ve değişen aile tanımı temalarını ele alıyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/kutudaki-koyun.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/kutudaki-koyun-izle/", category = "Film"),
