    Movie(id = 1100185, title = "Sadece Bir Gece One Night Only", overview = "Yeni terk edilmiş Owen ile romantizme hâlâ inanan Allie, şehirde basit bir kaçamaklardan fazlasını arayan belki de tek bekârlardır. Karşılaştıkları anda aralarında bir kıvılcım doğar; ancak yanlış anlaşılmalar ve beklenmedik yan maceralar gecelerini karmaşık hâle getirir ve onları sürekli birbirlerinden uzak tutar. Şehir boyunca hem birbirlerine doğru hem de birbirlerinden kaçarken, aslında aradıkları şeyin sandıklarından çok daha yakın olabileceğini fark edebilirler.", poster = "https://rfilmizle.com/wp-content/uploads/2026/07/sadece-bir-gece.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/sadece-bir-gece-izle-2/", category = "Film"),
