    Movie(id = 1100195, title = "Mevlana: Mest-i Aşk", overview = "Mest-i Aşk, Şems-i Tebrizi’nin esrarengiz kayboluşunu ve bu olayın Mevlana’nın hayatındaki derin izlerini konu ediyor. Mevlana'nın yakın dostu olan Şems-i Tebrizi, ardından hiçbir iz bırakmadan ortadan kaybolur. Onun bu esrarengiz kaybı başta Mevlana olmak üzere çevresindekiler için büyük bir endişe oluşturur. Şems bir kaza mı yaşamıştır ya da inzivaya mı çekilmitir? Yoksa düşmanı da çok olan Şems bir cinayete mi kurban gitmiştir?", poster = "https://rfilmizle.com/wp-content/uploads/2026/09/mevlana-mest-i-ask.jpg", backdrop = "", year = "2024", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/mevlana-mest-i-ask-izle/", category = "Film"),
