    Movie(id = 1100198, title = "Above & Below Derin Dehşet", overview = "Kafeste oksijenleri tamamen tükenmek üzere olan Tatiana ve Kaley, köpekbalıklarının saldırısını kartel dalgıçlarına doğru kanallayarak su altındaki muhafızlardan kurtulmayı başarırlar. Uyuşturucu çantasını da yanlarına alarak yüzeye çıkan kızlar, teknedeki arkadaşlarıyla güçlerini birleştirip Antonio Banderas’ın canlandırdığı çete lideri Burns ve adamlarına karşı amansız bir tekne baskını düzenlerler. Burns, kendi kurduğu o ölümcül ağın ortasında kalarak okyanusun derin sularına gömülürken, hayatta kalan gençler yaralı bir şekilde de olsa sahil güvenliğe ulaşmayı başarırlar. Film, gençlerin lüks yatın enkazından kurtulup kurtarma botunda derin bir…", poster = "https://rfilmizle.com/wp-content/uploads/2026/07/above-and-below.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/above-and-below-izle/", category = "Film"),
