    Movie(id = 1100206, title = "A Prayer Before Dawn Şafaktan Önce", overview = "Tayland'ın en ünlü hapishanelerinden birinde 3 yıl hapis yatmış genç İngiliz boksör Billy Moore'un, gözlerinize inanamayacağınız anılarından uyarlanan gerçek bir hikaye. Bir anda kendisini uyuşturucunun ve hapishane içi çete savaşlarının içinde bulan Moore, hapishane yönetimi Muay Thai boks turnuvalarına katılabileceğini söylediğinde, bunun kurtulmak için tek şansı olabileceğini düşünür. Billy, özgürlüğünü kazanmak için bir dövüşten başka bir dövüşe savrulduğu, aksiyon ve yumruklarla dolu, sonunda da özgürlüğünden başka kaybedecek bir şeyi olmadığı bir maceraya sürüklenir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/safaktan-once.jpg", backdrop = "", year = "2018", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/safaktan-once-izle/", category = "Film"),
    Movie(id = 1100207, title = "Kutup Köpekleri 3", overview = "Buzlarla kaplı Taigasville kasabasında yaşayan yaramaz mors Otto, gizemli bir kitabı yanlışlıkla açınca kendini rüya dolu, fantastik bir dünyada bulur! Yanında her zamanki gibi akıllı ve cesur Jade, eğlenceli PB ve hızlı Swifty vardır. Bu dostlar, karlar altındaki büyülü sırrı çözmek için birlikte heyecan dolu bir yolculuğa çıkar. Eve dönebilmek için Otto’nun dostluğun gücüne ve kalbinin sıcaklığına inanması gerekir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/kutup-kopekleri-3.jpg", backdrop = "", year = "2025", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/kutup-kopekleri-3-izle/", category = "Film"),
    Movie(id = 1100208, title = "Le Cri des gardes The Fence", overview = "Horn, ortağı Léone'yi Cal ile paylaştığı kulübeye davet ederken, Alboury adında bir adam ortaya çıkar. Kardeşinin olay yerinde öldürülmesinin ardından cesedi geri getirilene kadar orada kalır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/le-cri-des-gardes.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/le-cri-des-gardes-izle/", category = "Film"),
    Movie(id = 1100209, title = "Sanguine", overview = "Ülkenin en rekabetçi acil servislerinden birinde stajyer olarak çalışan genç Margot, yüksek baskı ortamında zorluklar yaşıyor. Yaşıtları olan ve garip semptomlar gösteren birçok hasta geldiğinde, kendi vücudunda da endişe verici değişimler meydana gelmeye başlıyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/sanguine.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/sanguine-izle/", category = "Film"),
    Movie(id = 1100210, title = "Wife & Dog", overview = "Saygın ve parlak bir bilim insanı, piyasadaki en popüler böcek ilacının doğaya ve insan sağlığına ölümcül zararlar verdiğini kanıtlayan kanıtlar elde eder. Gerçeği kamuoyuna duyurmak istediğinde, devasa kimya şirketi tüm serveti ve nüfuzunu onu susturmak için seferber eder. Bilimsel gerçekler ile dev şirketlerin acımasız baskısı arasında kalan bilim insanının, gerçeği savunmak adına başlattığı soluksuz mücadele.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/wife-dog.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/wife-dog-izle/", category = "Film"),
    Movie(id = 1100211, title = "Behemoth!", overview = "Müzisyen bir aileden gelen ve Los Angeles'a dönen bir müzisyenin hikayesini anlatıyor. Film müziklerine ve bu müzikleri yapan insanlara yazılmış bir aşk mektubu.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/behemoth.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/behemoth-izle/", category = "Film"),
    Movie(id = 1100212, title = "Man of Tomorrow", overview = "Metropolis ve dünya, ne Superman'in tek başına durdurabileceği ne de Lex Luthor'un insan zekasıyla çözebileceği büyüklükte küresel bir tehditle karşı karşıya kalır. Yıllardır birbirlerinin en büyük düşmanı olan Çelik Adam ve Luthor, gezegenin yok oluşunu engellemek için ego ve nefretlerini bir kenara bırakıp ortak hareket etmek zorunda kalır. Çelik kaslar ile keskin zekanın zoraki birleşimi, adalet ve hırs arasındaki ince çizgiyi yeniden çizer.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/man-of-tomorrow.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/man-of-tomorrow-izle/", category = "Film"),
    Movie(id = 1100213, title = "Victorian Psycho Viktorya Dönemi Psikopatı", overview = "1858 yılında Viktorya dönemi İngiltere'sinde geçen film, karanlık ve psikopatik eğilimlerini gizleyen Winifred Notty adlı bir mürebbiyenin, çalışanların gizemli şekilde kaybolduğu ücra bir malikaneye gidişini ve katı toplumsal kuralları kanlı bir kaosa çevirmesini anlatır", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/victorian-psycho.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/victorian-psycho-izle/", category = "Film"),
    Movie(id = 1100214, title = "Boonie Bears: The Hidden Protector – Boonie Bears: Gizli Koruyucu", overview = "Balkanlar ve ormanın sevimli dostları Briar, Bramble ve Oduncu Vick, Doğu mitolojisinin efsanevi yaratığı Yıl Canavarı Nian ile beklenmedik bir şekilde karşı karşıya gelir. Nian'ın dokunuşuyla gizemli ve üstün güçler kazanan kafadarlar, kendilerini büyüleyici olduğu kadar kaotik ve tehlikeli Eve City'nin derinliklerinde bulurlar. Yeni yeteneklerini keşfetmeye çalışan üçlü, şehrin gizli dengelerini korumak ve evlerine dönebilmek için nefes kesen bir maceraya atılır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/e7868ae587bae6b2a1c2b7e5b9b4e5b9b4e69c89e7868a.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/%e7%86%8a%e5%87%ba%e6%b2%a1%c2%b7%e5%b9%b4%e5%b9%b4%e6%9c%89%e7%86%8a-izle/", category = "Film"),
    Movie(id = 1100215, title = "Ustoppelig Durdurulamaz", overview = "Filmin merkezinde, on yaşındaki Erik'in böbreğinde yaşayan küçük, cesur bir hücre olan Kaja (Amalie Stuve) yer alıyor. Diğer tüm hücreler olması gerektiği gibi bölünürken, Kaja bölünmüyor. Bölünemez, hayal kırıklığına uğramış ve kendi gözünde tamamen işe yaramaz bir hücre. Gerçekte nasıl çalıştığını öğrenmek için vücudunda çılgın bir yolculuğa çıkıyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/ustoppelig.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/ustoppelig-izle/", category = "Film"),
    Movie(id = 1100216, title = "Melodi ve Neşeli Notalar", overview = "Melodi ve Efe, İstanbul’da okuyan iki yakın arkadaştır. Okulun sevilen müzik öğretmenlerinin ayrılacağını öğrenmeleriyle, bu durumu değiştirebilecek tek fırsatın Büyük İstanbul Müzik Yarışması olduğunu keşfederler. Umutsuzluk içindeki Melodi, İstanbul Boğazı kıyısında karşılaştığı sevimli davul Damdam ile birlikte bir müzik grubu kurmaya karar verir. Kadıköy İskelesi’nden klarnet, Karaköy’den saz ve Taksim Meydanı’ndan farklı enstrümanların katılımıyla ekip tamamlanır. Ancak İstanbul’un karanlık yüzünü temsil eden Liza, grubun en önemli parçası olan kanunu kaçırır. Melodi, Efe ve Damdam; İstanbul’un sokaklarında ilerleyen bu müzik dolu…", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/melodi-ve-neseli-notalar.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/melodi-ve-neseli-notalar-izle/", category = "Film"),
    Movie(id = 1100217, title = "Josephine", overview = "8 yaşındaki Josephine, Golden Gate Park'ta tesadüfen bir suça tanık olduktan sonra, güvenliğini yeniden sağlamanın bir yolunu ararken, romantikler onu teselli etmekte çaresiz kalır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/josephine.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/josephine-izle/", category = "Film"),
    Movie(id = 1100218, title = "Sosyal Hesaplaşma The Social Reckoning", overview = "Sosyal Hesaplaşma, Facebook bünyesinde mühendis olarak çalışan Frances Haugen'ın, teknoloji devinin büyük bir gizlilikle sakladığı sırları gün yüzüne çıkarma sürecine odaklanıyor. Şirketin iç işleyişine dair sarsıcı gerçekleri ifşa etmeye karar veren Haugen, bu zorlu yolculukta Wall Street Journal muhabiri Jeff Horwitz ile iş birliği yapıyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/the-social-reckoning.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/the-social-reckoning-izle/", category = "Film"),
    Movie(id = 1100219, title = "Groove Tails", overview = "Görkemli ve renkli bir yeraltı dans kulübünün kapıları aralanıyor. Sokakların ritmiyle büyüyen yetenekli kedi Biggie, farelerin ve kedilerin amansız bir rekabet içinde olduğu gizli dans turnuvasına katılır. Yıllardır süregelen türler arası düşmanlığı ve sokak raconlarını dans pistinde yıkmaya çalışan Biggie, hem büyük ödülü kazanmak hem de mahallenin saygısını elde etmek için yüksek tempolu bir mücadeleye girişir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/groove-tails.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/groove-tails-izle/", category = "Film"),
    Movie(id = 1100220, title = "La Llorona’nın İntikamı – The Revenge of La Llorona", overview = "Meksika mitolojisinin en korkutucu intikamcı ruhu La Llorona yeniden ortaya çıktığında, zaten kopuk olan bir aile kendisini kelimenin tam anlamıyla bir kabusun ortasında bulur. Çocuklarını lanetli ruhun gazabından korumak isteyen aile, geçmişte gömdükleri acı dolu anılarla ve görüşmedikleri büyükbabalarıyla yüzleşmek zorunda kalır. Kadim ritüellerin ve bağların sınandığı, nesiller boyu süren bir hayatta kalma mücadelesi.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/MV5BYjZlZThhY2EtNGRkMC00YWJlLTgwN2YtODExZWVlYjYwOGFiXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/the-revenge-of-la-llorona-izle/", category = "Film"),
    Movie(id = 1100221, title = "The Debut İlk Gösterim", overview = "Utangaç bir kadın, beklenmedik bir şekilde küçük çaplı bir müzikal yapımında rol alır. Hem kararlı hem de gizemli bir yönetmenin yönetiminde, rolünü iyiden iyiye benimsemeye ve küçük sahnenin dünyasında giderek kendini kaybetmeye başlar...", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/the-debut.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/the-debut-izle/", category = "Film"),
    Movie(id = 1100222, title = "Orman Ritmi 2 – Jungle Beat 2: The Past", overview = "Afrika ormanının sevilen hayvan ekibi, uzaylıların açık bıraktığı gizemli bir zaman portalına kazara adım atarak tarih öncesi çağlara düşer. Kendi dönemlerine geri dönebilmek için kadim dinozorların yardımına ihtiyaç duyan sevimli dostlarımız, beklediklerinden çok daha kaotik bir dünyayla karşılaşır. Eli sopalı mağara uzaylılarının istilası altında olan dinozorlarla güçlerini birleştiren ekip, hem geçmişi kurtarmak hem de evlerine dönmek için nefes kesen bir maceraya atılır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/jungle-beat-2-the-past.jpg", backdrop = "", year = "2025", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/jungle-beat-2-the-past-izle/", category = "Film"),
    Movie(id = 1100223, title = "L’inconnue Bilinmeyen Kadın", overview = "İçe kapanık bir fotoğrafçı olan David Zimmerman, arkadaşlarının ısrarıyla katıldığı çılgın bir partiyle rutininin dışına çıkar. Burada tanıştığı gizemli bir kadın, kısa sürede onun zihnini tamamen ele geçirir. David, bu kadına karşı giderek artan bir takıntı geliştirir ve onu izlemeye başlar. Ancak gece sona erip şafak söktüğünde, her şey geri dönülmez biçimde değişir. David, gözlerini açtığında artık kendi bedeninde değildir; takıntı haline getirdiği kadının bedeninde uyanmıştır.\"The Godfather\" Efsanesi, 2027'de Şimdiye Kadar Hiç Anlatılmamış Bir Karakterin Hikayesiyle Geri Dönüyor Sinema tarihinin…", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/linconnue.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/linconnue-izle/", category = "Film"),
    Movie(id = 1100224, title = "Şapkalı Kedi The Cat in the Hat", overview = "Şapkalı Kedi, yeni bir şehre taşınmakla uğraşan iki kardeşe kaos ve yaramazlık getiren akıllı bir kedinin hikayesini konu ediyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/the-cat-in-the-hat.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/the-cat-in-the-hat-izle/", category = "Film"),
    Movie(id = 1100225, title = "Kartopu Oyunları Reisen mot Nord", overview = "Genç Gerda, gizemli bir şekilde ortadan kaybolan arkadaşı Kai'yi aramak için bilinmeyene doğru yola çıkar. Yolculuğu sırasında Gerda, insanlarla, kuşlarla, hayvanlarla ve iyi kalpli bir cadıyla arkadaş olur; ancak onu izleyen düşmanca, görünmez bir düşmanın farkında değildir: Karlar Kraliçesi ve onun gargoyle çırağı Louie. Kötü kraliçe, Kai'yi kuzeyde, Finnmark'taki buz sarayında tutsak tutmaktadır. Gerda ve Kai sonunda kraliçenin pençelerinden kurtulur ve en mutlu Noel'e yetişmek için tam zamanında evlerine dönerler.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/reisen-mot-nord.jpg", backdrop = "", year = "2025", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/reisen-mot-nord-izle/", category = "Film"),
    Movie(id = 1100226, title = "Kötü Periler – Bad Fairies", overview = "kuralları çiğnemenin getirdiği kaotik sonuçları merkezine alıyor. Yasaklı büyüler yapmaktan, prenseslerin kaderine fütursuzca müdahale etmeye kadar her türlü kural ihlalini imzalayan çılgın periler grubu, yanlışlıkla periler diyarının en büyük felaketini serbest bırakır. Yarattıkları devasa kaosu yine kendi kural tanımaz ve sıra dışı yöntemleriyle çözmek zorunda kalan ekibin kahkaha dolu macerası.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/bad-fairies.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/bad-fairies-izle/", category = "Film"),
    Movie(id = 1100227, title = "Day Drinker", overview = "Gizemli bir yabancı, sevgilisini kaybeden yaslı bir barmenle beklenmedik bir bağ kurar ve hayatları beklenmedik şekillerde iç içe geçer.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/day-drinker.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/day-drinker-izle/", category = "Film"),
    Movie(id = 1100228, title = "Demir Çocuk – Le Corset", overview = "Konu özeti yüklenen HTML dosyalarında bulunmuyor. Kaynak sayfayı açabilirsiniz.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/le-corset.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/le-corset-izle/", category = "Film"),
    Movie(id = 1100229, title = "Wings Of Freedom – Özgürlük Kanatları", overview = "Kendi güvenli alanından dışarı adım atmamış evine bağlı kartal Salana, beklenmedik bir kriz sonucunda ormanındaki kuş kolonisini terk etmek zorunda kalır. Hayvan Hava Kuvvetleri'nin gözü pek ve kural tanımaz kırlangıcı Pirro ile yolları kesişen Salana, kendisini gökyüzünde nefes kesen bir takibin ortasında bulur. Mizaçları tamamen zıt olan bu iki kuş, dünyayı ele geçirmeye çalışan kötü niyetli bir yapay zekayı durdurmak için omuz omuza vererek destansı bir maceraya atılır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/wings-of-freedom.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/wings-of-freedom-izle/", category = "Film"),
    Movie(id = 1100230, title = "Mürekkep Ink", overview = "Her gece, ışıklar sönüp tüm şehir uykuya daldığında, insan gözünün göremediği iki güç arasındaki ezeli ve ebedi mücadele tekrarlanır. Aydınlığın gücü, rüyalarımıza umut ve güzel rüyaların kuvvetini taşırken; karanlığın gücü, karabasanlar ve kabuslarımızdan sorumludur. John ve küçük kızı Emma bu fantastik mücadelenin ortasında kalacaklardır. John, bir kabus getirenin kontrolünde, kendisini sadece para kazanmaya adamış, kayıp bir ruhtur. Kabus getirenler, Emma'ya ulaşmak için onun kayıp ruhunu kullanmaya karar verirler. Bir gece Emma'nın küçük ruhu bir umacı tarafından kaçırılır ve Emma komaya…", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/murekkep.jpg", backdrop = "", year = "2009", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/murekkep-izle/", category = "Film"),
    Movie(id = 1100231, title = "Helldivers", overview = "distopik bir gelecekte askeri propagandanın ve abartılı vatanseverlik söylemlerinin absürtliğini aksiyonla harmanlıyor. Süper Dünya'nın kusursuz görünen \"demokrasi\" vaatleriyle cepheye sürülen genç askerler, kendilerini uzaylı cehenneminin ortasında bulur. Bir yandan devasa yaratıklar ve ölümcül robotlarla savaşırken, diğer yandan sistemin onları tek kullanımlık birer piyon olarak gördüğü gerçeğiyle yüzleşen bir manganın kaotik macerası.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/helldivers.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/helldivers-izle/", category = "Film"),
    Movie(id = 1100232, title = "The Legend of Zelda", overview = "Film, Prenses Zelda'yı kurtarmak isteyen savaşçı Link'in hikayesini anlatan macera bilgisayar oyunu \"The Legend of Zelda\"dan uyarlanıyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/the-legend-of-zelda.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/the-legend-of-zelda-izle/", category = "Film"),
    Movie(id = 1100233, title = "K-Pop: The Debut", overview = "Amerika’daki rahat hayatını geride bırakıp Seul’e adım atan Kore asıllı Amerikalı bir üniversite öğrencisi, ülkenin en büyük K-Pop yarışma programına katılır. Zorlu stajyerlik kültürü, acımasız koreografiler ve dil bariyeriyle yüzleşirken; hem kökleriyle yeniden bağ kurar hem de hayallerindeki sahneye ulaşmak için ter döker. İki farklı kültür arasında sıkışan genç adam, kendi özgün sesini bularak K-Pop dünyasında var olma mücadelesi verir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/k-pop-the-debut.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/k-pop-the-debut-izle/", category = "Film"),
    Movie(id = 1100234, title = "Arınma", overview = "Amerikalı rahibe Cecilia, İtalya’daki göz alıcı bir manastırdan davet alır. Cecilia burada çok sıcak karşılanmıştır. Fakat bu kusursuz mekânın bazı karanlık ve korkutucu sırlar barındırdığını çok geçmeden anlar. Yeni evi, uğursuz ve anlatılamaz dehşetler yaşayacağı bir kâbusa dönüşür.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/arinma.jpg", backdrop = "", year = "2024", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/arinma-izle-2/", category = "Film"),
    Movie(id = 1100235, title = "Dynamic Duo", overview = "Gotham'ın gölgelerinde büyüyen Dick Grayson ve Jason Todd, adalet anlayışları ve geleceğe dair vizyonları şekillenirken ilk arkadaşlıklarının kırılma noktasıyla yüzleşir. Bir zamanlar aynı ideali paylaşan bu iki genç, zamanla sokakların getirdiği sert gerçekler karşısında farklı yollara sapar. Aralarındaki bağ sarsılırken, ortaya çıkan yeni bir \"Dinamik İkili\", iki gencin hem kendi kimliklerini hem de aralarındaki dostluğun gerçek anlamını sorgulamalarına neden olur.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/dynamic-duo.jpg", backdrop = "", year = "2028", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/dynamic-duo-izle/", category = "Film"),
    Movie(id = 1100236, title = "Gremlins 3", overview = "sevimli Mogwai’lerin ve onların yıkıcı dönüşümlerinin modern çağın teknolojisiyle kesişmesini merkezine alıyor. Kuralların çiğnenmesiyle ortaya çıkan yırtıcı yaratıklar, bu kez sadece bir kasabayı değil; dijital ağları, akıllı ev sistemlerini ve modern şehir altyapısını hedef alarak kaosu büyütür. Teknolojinin ortasında kalan bir çocuğun, kontrolden çıkan canavarları durdurmak için girdiği eğlenceli ve tehlikeli bir mücadele.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/gremlins-3.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/gremlins-3-izle/", category = "Film"),
    Movie(id = 1100237, title = "Direniş – Moulin", overview = "İkinci Dünya Savaşı'nın en karanlık döneminde, işgal altındaki Fransa'ya paraşütle inen Jean Moulin, General de Gaulle'ün talimatıyla dağınık halde yürütülen direniş gruplarını tek bir çatı altında toplamakla görevlendirilir. Bütün Fransız Yeraltı Örgütü'nü birleştirerek işgalcilere karşı devasa bir güç oluşturan Moulin, hain bir ihbar sonucu Gestapo şefi Klaus Barbie’nin eline düşer. Uğradığı ağır işkencelere rağmen direnişçilerin isimlerini vermeyen Moulin'in sarsılmaz sessizliği, Fransa’nın özgürlüğe giden kaderini belirler.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/moulin.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/moulin-izle/", category = "Film"),
    Movie(id = 1100238, title = "The Haunting of Hotel Transylvania Hotel Transylvania’nın Hayaleti", overview = "The Haunting of Hotel Transylvania, babasının emekliliğinin ardından ailenin canavar otelini işletmeye başlayan Dracula'nın kızı Mavis'in hikayesini konu ediyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/the-haunting-of-hotel-transylvania.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/the-haunting-of-hotel-transylvania-izle/", category = "Film"),
    Movie(id = 1100239, title = "La Fille dans les nuages – Girls in the Clouds", overview = "Çevre koruyucularını konu alan bir kitap serisinin hayranı olan 12 yaşındaki Providence, serinin gizemli yazarından yazılan her şeyi gerçeğe dönüştüren sihirli bir hokka/tüy kalem teslim alır. Hayallerini gerçeğe dönüştürme fırsatını yakalayan küçük kız, doğaya verilen zararları düzeltmek için küresel bir maceraya atılır. Konuşma ve boyut değiştirme yeteneği kazanan sevimli ama mızmız kobayı Airbag ile birlikte, hayal gücünün sınırlarını zorlayarak gezegeni büyük bir yıkımdan kurtarmak için tehlikeli bir yolculuğa çıkar.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/la-fille-dans-les-nuages.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/la-fille-dans-les-nuages-izle/", category = "Film"),
