    Movie(id = 1100242, title = "Bir Minecraft Filmi 2: Squared", overview = "Wither Storm geri döner ve ölümcül bir olaya sebep olur.Yeni yapay zekâ teknolojisi Türkiye genelinde hızla yayılıyor: nedenini öğrenin. AI APP \"The Godfather\" Efsanesi, 2027'de Şimdiye Kadar Hiç Anlatılmamış Bir Karakterin Hikayesiyle Geri Dönüyor Sinema tarihinin en büyük kült yapımlarından biri olan \"The Godfather\", otuz yılı aşkın bir aranın ardından bu kez ailenin tek kızı Connie Corleone’nin bilinmeyen yükselişini anlatacak yeni bir kitap ve filmle geri dönüyor. Türkiye’de bazı vatandaşlar yapay zekâ sayesinde 2.000 Euro’ya kadar ek gelir elde ediyor!…", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/bir-minecraft-filmi-2-squared.jpg", backdrop = "", year = "2027", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/bir-minecraft-filmi-2-squared-izle/", category = "Film"),
