    Movie(id = 1100251, title = "Tavuk Hen", overview = "Tavuk çiftliğinden kaçan kahramanımız, yıkılmaya yüz tutmuş bir restoranın avlusuna sığınır. Burada aşkı keşfeder, kümesin acımasız hiyerarşisiyle yüzleşir ve yumurtalarını gözü doymaz sahibinden korumak için amansız bir mücadeleye girişir. Onun annelik yolundaki bu absürt ama dokunaklı arayışı; insan hayatının karmaşık tavizlerine ve sessiz direnişlerine ayna tutuyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/tavuk.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/tavuk-izle/", category = "Film"),
    Movie(id = 1100252, title = "Düğün Şarkıcısı", overview = "001 yılında büyük hayallerle İstanbul’a gelen genç caz şarkıcısı Şahnaz, Amerika’da müzik eğitimi alıp dünya sahnelerinde yer almayı hedeflemektedir. İstiklal Caddesi’nde sokak müzisyenliği yaparken keşfedilen Şahnaz, işletmeci Muzaffer’in açtığı Urban Jazz Bar’ın solisti olur ve kısa sürede Beyoğlu’nun saygın müzik çevrelerinde adından söz ettiren bir sanatçıya dönüşür. Ancak yıllar geçtikçe yalnızca Şahnaz’ın değil, İstanbul’un da ritmi değişir. Terör saldırıları, ekonomik krizler, toplumsal çalkantılar ve pandemi, onun hayallerini birer birer elinden alır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/dugun-sarkicisi-1784920611.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/dugun-sarkicisi-2026/", category = "Film"),
