    Movie(id = 1100274, title = "Eski Toprak (Old Guy)", overview = "Kariyerinin sonuna yaklaşan kiralık katil Danny Dolinski, henüz işinin bitmediğini düşünmektedir. Çalıştığı şirket onu sahaya geri çağırınca oldukça heyecanlanır ancak işi, yeni nesil genç bir kiralık katil olan Wihlborg'u eğitmektir. Farklı dönemlerin insanları olan bu ikiliye, rakip suç örgütünün üst düzey üyelerini ortadan kaldırma görevi verilince kendi işverenlerinin asıl amacını açığa çıkarırlar. Danny'nin deneyimi Wihlborg'un zekâsıyla birleşince durdurulamaz bir ikili ortaya çıkar.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/eski-toprak.jpg", backdrop = "", year = "2024", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/eski-toprak-izle/", category = "Film"),
