    Movie(id = 1100279, title = "Canavar Beast", overview = "Beast 2026 izleyin Beast 2026 ne zaman çıkacak? Beast 2026 platformu - Oyuncuları kimler? Beast 2026 Fragman ve güncel bilgiler limonfilm izle Beast tek parça izleyin Filmin o tozlu, sıcak ve her yerinden vahşet fışkıran o atmosferi beni benden aldı. O güneşin altındaki o kavurucu sessizlik, o her bir dal çıtırtısında zıplayan o karakterlerin o gerginliği... Yönetmen resmen \"Doğa seni yutmak istediğinde, ne silahın ne de zekan seni kurtarabilir; sadece o içindeki o hayvani hırs hayatta tutar\" mesajını her karede…", poster = "https://rfilmizle.com/wp-content/uploads/2026/04/beast.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/beast-izle/", category = "Film"),
    Movie(id = 1100280, title = "12 Savaşçı – 12 Warriors", overview = "Tek bir kuralın geçerli olduğu bir kilitli bina: \"Son kalan kazanır.\" Ancak aynı kapana kısılan 12 farklı karakterin geçmişleri, vicdani değerleri ve stratejileri süreç ilerledikçe çakışır. Birbirlerini avlamak zorunda olan dövüşçüler arasında kurulan zoraki ittifaklar, ihanetler ve psikolojik kırılmalar; aksiyonun ötesinde insan doğasının hayatta kalma güdüsüyle sınandığı sürükleyici bir drama sunuyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/12-warriors.jpg", backdrop = "", year = "2025", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/12-warriors-izle/", category = "Film"),
    Movie(id = 1100281, title = "Damat Mektebi", overview = "ham ve bocalayan genç erkeklerin empati ve saygı çerçevesinde geçirdiği duygusal dönüşümü odağına alıyor. Dinlemeyi, hislerini ifade etmeyi ve kadınlara saygılı yaklaşmayı öğrenen gençler, kabuklarını kırarak gerçek özgüvenle tanışır. Yüzeysel beklentilerin ötesine geçen bu kişisel gelişim süreci, köyün genç kadınlarının da kalbini ve bakış açısını yeniden kazanmalarını sağlar.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/8ea8648a5709340fabdaacb456d90aa7.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/damat-mektebi-2026/", category = "Film"),
