    Movie(id = 1100302, title = "The Kings Warden", overview = "Joseon Hanedanlığı döneminde geçen bu eser, Joseon'un 6. kralı Danjong'un Gangwon Eyaleti'ndeki Yeongwol'a sürgün edilmesinin öyküsünü anlattığı söylenmektedir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/ec9995eab3bc-ec82aceb8a94-eb82a8ec9e90.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/%ec%99%95%ea%b3%bc-%ec%82%ac%eb%8a%94-%eb%82%a8%ec%9e%90-izle/", category = "Film"),
    Movie(id = 1100303, title = "Ten Years of Loving You", overview = "17 yaşında, evlat edinilmiş bir çocuk olan Wen Heng, biyolojik ailesi tarafından sonunda bulunur ve Pekin'deki aile evine geri getirilir. Orada, yeni ailesiyle birlikte yeni hayatına uyum sağlamaya çalışır, ancak evlat edindikleri kız kardeşi onun varlığı tarafından tehdit edildiğini hissedip sinir krizi geçirmeye başladığında sorunlar ortaya çıkar. Ailenin huzurunu korumak için Wen Heng'den yan taraftaki bir aile dostunun evine taşınması istenir. Orada Wen Heng, Yan Xi ile tanışır ve ikisi birlikte yaşayıp okula birlikte gittiklerinde yavaş yavaş yakınlaşmaya başlarlar. Ama…", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/ten-years-of-loving-you.jpg", backdrop = "", year = "2022", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/ten-years-of-loving-you-izle/", category = "Film"),
