    Movie(id = 1100305, title = "Doğum Günü Partisi-The Birthday Party", overview = "Aristotle Onassis’e benzer bir Yunan milyarder olan Markos Timoleon, kızının 25. doğum gününü özel adasında kutlamaktadır. Ancak görkemli davet, gücünü tehdit eden ve hayatını altüst edecek beklenmedik olaylara sahne olur.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/dogum-gunu-partisi.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/dogum-gunu-partisi-izle/", category = "Film"),
