    Movie(id = 1100307, title = "Roza", overview = "Vahşi infazın gerçekleşmesinin ardından, Roza’nın trajik ölümüyle birlikte aile tamamen parça pinçik olarak dağılır. Anne Fate akıl sağlığını kaybedip derin bir sessizliğe gömülürken, cinayeti işleyen ağabey ve baba polisin düzenlediği operasyonla tutuklanarak cezaevine gönderilir. Film, töre ve cehalet uğruna feda edilen gencecik bir hayatın ardından geride kalan bu devasa enkazı ve vicdan azabını gösteren tokat gibi sarsıcı bir sonla noktalanır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/07/roza.jpg", backdrop = "", year = "2023", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/roza-izle/", category = "Film"),
    Movie(id = 1100308, title = "En Yakın Arkadaşım, Sevgilisi ve Ben (Mein bester Freund, seine Freundin und ich)", overview = "Rebecca başlangıçta Olli'nin gözünde Matze'yi hipnotize etmiş, onu evden ve arkadaşından koparan sinsi bir düşmandır. Ancak Olli planlarını devreye sokup Rebecca ile daha fazla didiştikçe, onun aslında göründüğü gibi biri olmadığını, hatta Matze'yi gerçekten mutlu ettiğini fark eder. Komik kumpaslar sürerken önyargı maskeleri düşer ve geriye gerçek sevginin kabulü kalır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/en-yakin-arkadasim-sevgilisi-ve-ben.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/en-yakin-arkadasim-sevgilisi-ve-ben-izle/", category = "Film"),
    Movie(id = 1100309, title = "Ailenin Şerefi", overview = "Ailenin Şerefi, hayatı boyunca ailesini arayan bir adamın hikayesini konu ediyor. Şeref, hayatı boyunca ailesini arayan bir adamdır. Beklenmedik bir anda ailesinin onu bulmasıyla hayatı bambaşka bir hal alır. Midyat'ın önde gelen ailelerinden birinin çocuğu olan Şeref, iftira yüzünden babasının hapse atılmasıyla ailesinin başına geçer. Babasının cezaevinden çıkarmaya çalışan Şeref, bu süreçte kendisini komik olayların içerisinde bulur.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/ailenin-serefi.jpg", backdrop = "", year = "2025", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/ailenin-serefi-izle/", category = "Film"),
    Movie(id = 1100310, title = "Kokteyl 2 Cocktail 2", overview = "On yıldır mutlu bir ilişki sürdüren Kunal (Shahid Kapoor) ve Diya (Rashmika Mandanna) , hayatlarını birlikte kurmuş, birbirlerine alışmış ve gelecek planlarını şekillendirmiş bir çifttir. Ancak ikilinin düzenli ve sakin yaşamı, eski ortak arkadaşları (Kriti Sanon) Ally’nin aniden hayatlarına geri dönmesiyle beklenmedik şekilde değişir. Ally’nin gelişi, geçmişte unutulduğu sanılan duyguları ve çözülmemiş meseleleri yeniden gün yüzüne çıkarır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/e0a495e0a589e0a495e0a49fe0a587e0a4b2-e0a5a8.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/%e0%a4%95%e0%a5%89%e0%a4%95%e0%a4%9f%e0%a5%87%e0%a4%b2-%e0%a5%a8-izle/", category = "Film"),
    Movie(id = 1100311, title = "To The Max Uçlarda Yaşamak", overview = "To the Max, imkansız bir dünya rekoruna ulaşmak için hayatlarını ortaya koyan profesyonel tırmanışçıların ve atlayışçıların hikayesidir. Nameless Tepesi'nin zirvesinden kendini boşluğa bırakmayı kafasına koyan Carlos, arkadaşlarıyla birlikte tarihe geçmenin planlarını yapar. Belgesel çekimleri eşliğinde ilerleyen bu devasa organizasyon, teknik aksaklıklar ve doğa olayları nedeniyle hızla bir hayatta kalma savaşına dönüşür.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/la-fiera.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/la-fiera-izle/", category = "Film"),
    Movie(id = 1100312, title = "Bana Şans Dileme – Don’t Say Good Luck", overview = "Sophie Birenbaum bir lise müzikalinde başrol oyuncusu olarak sahne almaya hazırlanır. Ancak yaşadığı evde, sahnedekinden çok daha çarpıcı bir dramayla yüzleşmek zorunda kalacaktır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/bana-sans-dileme.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/bana-sans-dileme-izle/", category = "Film"),
    Movie(id = 1100313, title = "Camp Rock 3", overview = "Camp Rock 3 2026 izle Camp Rock 3 2026 Konusu Nedir? Camp Rock 3 2026 Neden İzlenmeli? Camp Rock 3 2026 Hangi Platformda ve Nasıl İzlenir? Camp Rock 3 2026 IMDb Puanı ve Oyuncuları Bazen mecbur olmak zorunda kalırsınız değil mi kanka işte tam o noktadayız kanka.Valla kankam, bu Camp Rock 3 mevzusu tam bir \"nostalji damarından yakalama\" ve hayranların yıllardır bitmeyen o büyük rüyası! Disney Channel’ın o altın çağını yaşayan, Jonas Brothers ve Demi Lovato’nun o efsanevi enerjisiyle büyüyen…", poster = "https://rfilmizle.com/wp-content/uploads/2026/05/camp-rock-3.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/camp-rock-3-izle/", category = "Film"),
    Movie(id = 1100314, title = "Shackled", overview = "Gelecekte geçen distopik bir dünyada, geleneksel şartlı tahliye sisteminin yerini kısa adı R.A.P.P. olan bir program almıştır. Bu sisteme göre, beyaz yakalı bir eski mahkum (Sean), ölümcül kanser hastası sosyopat bir gangsterle eşleştirilir. Her iki suçlunun da kalbine cerrahi müdahaleyle patlayıcı şarjlar yerleştirilmiştir. İkisinden birinin yapacağı tek bir yanlış hamle, her ikisinin birden kalbindeki bombanın patlamasına ve anında infaz edilmelerine yol açacaktır. Birbirinden nefret eden bu iki adam, hayatta kalabilmek için zorunlu bir iş birliği yapmak zorundadır", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/shackled.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/shackled-izle/", category = "Film"),
