    Movie(id = 1100316, title = "The Convenience Store", overview = "yüksek saatlik ücreti nedeniyle bir markette gece vardiyasında çalışan bir üniversite öğrencisi kızı konu alır. Evine birkaç sokak uzaklıktaki bu dükkanda başlarda her şey normal ilerlerken, dükkanın otomatik kapısının durduk yere açılıp kapanmasıyla birlikte bir dizi doğunüstü ve ürpertici olay baş gösterir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/the-convenience-store.jpg", backdrop = "", year = "2025", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/the-convenience-store-izle/", category = "Film"),
    Movie(id = 1100317, title = "Kikirot Kirot", overview = "Evli bir çiftin hayatı, karısının kuzeninin eve taşınmasıyla altüst olur. Koca, kuzeninin daha önce gizlice görüştüğü striptizci olduğunu fark eder ve bu durum, baştan çıkarma, aldatma ve ifşa olma korkusunu tetikler.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/kikirot-kirot.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/kikirot-kirot-izle/", category = "Film"),
    Movie(id = 1100318, title = "Um Pai em Apuros Telaşlı Baba", overview = "Fred (Rafael Infante) ve tüm zamanını çocuklarına adayan anne Roberta (Dani Calabresa) yer almaktadır. Fred, kariyer basamaklarını tırmanırken aile hayatını sürekli ikinci plana atmaktadır. Beş çocuklu bu kalabalık ailenin tüm yükünü, ev işlerini ve çocukların bitmek bilmeyen okul/sosyal aktivitelerini tek başına sırtlayan Roberta artık tamamen tükenme noktasına gelir. Kendine vakit ayırmak isteyen Roberta, kız kardeşiyle birlikte ani bir kararla birkaç günlük bir tatile çıkmaya karar verir.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/um-pai-em-apuros.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/um-pai-em-apuros-izle/", category = "Film"),
