    Movie(id = 1100320, title = "Kaptan Nova Captain Nova", overview = "Kaptan Nova, gelecekte soğukkanlı bir jet pilotu ve insanlığın kurtarıcısı olarak eğitilmiştir. Ancak geçmişe ayak bastığı an, ciddiye alınmayan sıradan bir kız çocuğuna dönüşmenin şokunu yaşar. Kendi askeri yeteneklerine ve bilgisine güvenen Nova, etrafındaki büyüklerin kendisini sadece \"hayal gücü geniş bir çocuk\" olarak görmesini aşmak zorundadır. Film, onun romantik zihni ile çocuk bedeni arasındaki sıkışmışlığını ve pes etmeyen karakterini odağına alır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/captain-nova.jpg", backdrop = "", year = "2021", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/captain-nova-izle/", category = "Film"),
    Movie(id = 1100321, title = "Şeytandan Satılık For Sale by Exorcist", overview = "Mesleğinde uzman bir emlakçı ve sertifikalı bir şeytan çıkarıcı olan Susan Price, hayalindeki evi satın alıp huzurlu bir hayata adım atmaya hazırlanmaktadır. Ancak geçmişte temizlediği mülklerden kovduğu intikam hırslı ruhlar ve iblisler yeni evini hedef alınca işler çığırından çıkar. Susan, yuvasını adeta bir cehenneme çeviren bu doğaüstü musibetlerden kurtulmak için küfürbaz bir rahiple el ele verip kaotik bir mücadeleye girişmek zorunda kalır.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/seytandan-satilik.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/seytandan-satilik-izle/", category = "Film"),
    Movie(id = 1100322, title = "Hibla 2", overview = "Çevredeki erkeklerin (Andrew, Dante vb.) kurduğu psikolojik üstünlük ve manipülasyon ağları. Carla ve Jillian’ın bu manipülasyonlara karşı birlikte durma çabaları ama zamanla aralarındaki rekabet ve güvensizlik yüzünden nasıl zayıf düştükleri anlatılıyor.", poster = "https://rfilmizle.com/wp-content/uploads/2026/08/hibla-2.jpg", backdrop = "", year = "2026", score = 0.0, genreIds = emptyList(), provider = "RFilmizle", webUrl = "https://rfilmizle.com/hibla-2-izle/", category = "Film"),
